using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.ApplicationServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.PlottingServices;
public class Review{
static string root=Environment.GetEnvironmentVariable("CAD_POOL_JOB"),o=root+"/output/";static JavaScriptSerializer js=new JavaScriptSerializer(){MaxJsonLength=int.MaxValue};
[CommandMethod("ANPRINT",CommandFlags.Session)]public static void Go(){int iCount=0;try{var dm=Application.DocumentManager;var doc=dm.Open(root+"/output/drawing.dwg",true);dm.MdiActiveDocument=doc;using(doc.LockDocument()){Application.SetSystemVariable("BACKGROUNDPLOT",0);var db=doc.Database;var lm=LayoutManager.Current;var names=new List<string>();using(var t=db.TransactionManager.StartTransaction()){foreach(DBDictionaryEntry f in (DBDictionary)t.GetObject(db.LayoutDictionaryId,OpenMode.ForRead))if(!((Layout)t.GetObject(f.Value,OpenMode.ForRead)).ModelType)names.Add(f.Key);var ms=(BlockTableRecord)t.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);File.WriteAllText(o+"aud.json",js.Serialize(ms.Cast<ObjectId>().Select(id=>Visit.Dump((Entity)t.GetObject(id,OpenMode.ForRead),t)).ToList()));}
var readback=new Dictionary<string,Dictionary<string,int>>();lm.CurrentLayout="Model";readback["Model"]=DrawingProfile.Read();var frames=js.Deserialize<Builder.Config>(File.ReadAllText(root+"/scripts/cfg.json")).frames; var expected=frames.Select(f=>f.name).ToList();if(!new HashSet<string>(names).SetEquals(expected))throw new InvalidDataException("实际布局与出图清单不符");names=expected;var plots=new Dictionary<string,object>();int i=0;foreach(var n in names){lm.CurrentLayout=n;readback[n]=DrawingProfile.Read();doc.Editor.Regen();using(var t=db.TransactionManager.StartTransaction()){var l=(Layout)t.GetObject(lm.GetLayoutId(n),OpenMode.ForRead);var vps=l.GetViewports().Cast<ObjectId>().Select(id=>(Viewport)t.GetObject(id,OpenMode.ForRead)).Where(v=>v.Number!=1).ToList();if(vps.Count!=1||!vps[0].Locked||Math.Abs(vps[0].CustomScale-1/frames[i].scale)>.000001)throw new InvalidDataException("比例 "+n);var box=frames[i].b;var center=vps[0].ViewCenter;if(Math.Abs(center.X-(box[0]+box[2])/2)>0.01 || Math.Abs(center.Y-(box[1]+box[3])/2)>0.01)throw new InvalidDataException("Model viewport center: "+n);plots[n]=new{device=l.PlotConfigurationName,media=l.CanonicalMediaName,ctb=l.CurrentStyleSheet,plotStyles=l.PlotPlotStyles,locked=vps[0].Locked,scale=vps[0].CustomScale};using(var ps=new PlotSettings(false)){ps.CopyFrom(l);var pi=new PlotInfo(){Layout=l.ObjectId,OverrideSettings=ps};new PlotInfoValidator(){MediaMatchingPolicy=MatchingPolicy.MatchEnabled}.Validate(pi);using(var pe=PlotFactory.CreatePublishEngine()){pe.BeginPlot(null,null);pe.BeginDocument(pi,doc.Name,null,1,true,o+"page"+i+".pdf");pe.BeginPage(new PlotPageInfo(),pi,true,null);pe.BeginGenerateGraphics(null);pe.EndGenerateGraphics(null);pe.EndPage(null);pe.EndDocument(null);pe.EndPlot(null);}}}File.AppendAllText(o+"printed.txt",n+Environment.NewLine);i++;}if(i!=js.Deserialize<Builder.Config>(File.ReadAllText(root+"/scripts/cfg.json")).frames.Length)throw new InvalidDataException("页数");iCount=names.Count;File.WriteAllText(o+"drawing-profile.json",js.Serialize(new{views=readback,plots=plots,baseConfig=DrawingProfile.BaseConfig(db,false),sewageWidths=DrawingProfile.SewageWidths(db),dwgSha256=DrawingProfile.DrawingHash()}));}doc.CloseAndDiscard();File.WriteAllText(o+"validation.json",js.Serialize(new{passed=true,jobId=Environment.GetEnvironmentVariable("CAD_POOL_JOB_ID"),checks=new{layoutsPrinted=iCount,lockedScale=true,nativeReadBack=true}}));Application.DocumentManager.MdiActiveDocument.SendStringToExecute("CADPOOLCOMPLETE\n",true,false,false);}catch(System.Exception e){File.WriteAllText(o+"error.txt",e.ToString());Application.DocumentManager.MdiActiveDocument.SendStringToExecute("CADPOOLFAIL\n",true,false,false);}}
}